import os
import sys
import json
from . import cmd_login
from . import cmd_model
from .backup_utils import backup_existing_file


AHCLAUDE_DIR = os.path.expanduser("~/.ahdev")
SETTINGS_FILE = os.path.expanduser("~/.claude/settings.json")
BACKUP_FILE = os.path.join(AHCLAUDE_DIR, "settings.backup.json")


AHCLAUDE_ENV_BASE = {
    "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC": "1",
}


def get_claude_base_url() -> str:
    from .config.api_config import DEFAULT_BACKEND_API, get_backend_api

    backend_api = get_backend_api().rstrip("/")
    if backend_api == DEFAULT_BACKEND_API:
        return "http://gpt.autohome.com.cn"
    return backend_api


def log_error(msg: str):
    print(f"\n\033[31m[错误] {msg}\033[0m", file=sys.stderr)


def log_warning(msg: str):
    print(f"\n\033[33m[警告] {msg}\033[0m")


def log_success(msg: str):
    print(f"\033[32m{msg}\033[0m")


def create_directory():
    try:
        if not os.path.exists(AHCLAUDE_DIR):
            os.makedirs(AHCLAUDE_DIR)
    except PermissionError:
        log_error(f"无权限创建目录: {AHCLAUDE_DIR}")
        raise
    except OSError as e:
        log_error(f"创建目录失败: {e}")
        raise


def load_settings():
    if os.path.exists(SETTINGS_FILE):
        try:
            with open(SETTINGS_FILE, 'r', encoding='utf-8') as f:
                return json.load(f)
        except json.JSONDecodeError as e:
            log_warning(f"settings.json 格式错误，将重新创建: {e}")
            return {}
        except IOError as e:
            log_warning(f"读取 settings.json 失败: {e}")
            return {}
    return {}


def save_settings(settings):
    try:
        content = json.dumps(settings, ensure_ascii=False, indent=2)
        backup_existing_file(SETTINGS_FILE, "Claude Code settings.json", content)
        with open(SETTINGS_FILE, 'w', encoding='utf-8') as f:
            f.write(content)
    except IOError as e:
        log_error(f"保存 settings.json 失败: {e}")
        raise


def warn_overwrite():
    if os.path.exists(SETTINGS_FILE):
        with open(SETTINGS_FILE, 'r', encoding='utf-8') as f:
            existing = json.load(f)
        if existing.get("hooks") or existing.get("env"):
            log_warning("检测到已存在的 hooks 或 env 配置，将被覆盖")
            print(f"  现有 hooks: {list(existing.get('hooks', {}).keys())}")
            print(f"  现有 env: {list(existing.get('env', {}).keys())}")


def get_ahclaude_cmd():
    import shutil
    import sys

    def to_bash_path(path: str) -> str:
        normalized = path.replace("\\", "/")
        if len(normalized) >= 2 and normalized[1] == ":":
            drive = normalized[0].lower()
            rest = normalized[2:]
            if rest.startswith("/"):
                return f"/{drive}{rest}"
            return f"/{drive}/{rest}"
        return normalized

    cmd = shutil.which("auto++")
    if cmd:
        if sys.platform == "win32":
            return f'"{cmd}"'
        return cmd

    python_exec = sys.executable
    if sys.platform == "win32":
        return f'"{to_bash_path(python_exec)}" -m ahclaude_plugin'
    return f'"{python_exec}" -m ahclaude_plugin'

def is_ahclaude_command(command: str) -> bool:
    """检查命令是否属于 auto++"""
    if not command:
        return False
    return "auto++" in command or "ahclaude" in command


def clean_ahclaude_hooks(settings: dict):
    """清理所有 ahclaude 相关的 hooks"""
    if "hooks" not in settings:
        return

    hook_types = ["PostToolUse", "UserPromptSubmit", "SessionStart", "PreToolUse"]
    for hook_type in hook_types:
        if hook_type in settings["hooks"]:
            original_len = len(settings["hooks"][hook_type])
            settings["hooks"][hook_type] = [
                hook for hook in settings["hooks"][hook_type]
                if not any(
                    is_ahclaude_command(sub_hook.get("command", ""))
                    for sub_hook in hook.get("hooks", [])
                )
            ]
            removed = original_len - len(settings["hooks"][hook_type])
            if removed > 0:
                print(f"  已清理 {removed} 个旧的 {hook_type} Hook")

            if not settings["hooks"][hook_type]:
                del settings["hooks"][hook_type]

    if not settings["hooks"]:
        del settings["hooks"]


def configure_hooks():
    settings = load_settings()

    clean_ahclaude_hooks(settings)

    if "hooks" not in settings:
        settings["hooks"] = {}

    ahclaude_cmd = get_ahclaude_cmd()

    settings["hooks"]["PostToolUse"] = [{
        "matcher": "Write|Edit|MultiEdit",
        "hooks": [{
            "type": "command",
            "command": f"{ahclaude_cmd} claude edit"
        }]
    }]
    settings["hooks"]["UserPromptSubmit"] = [{
        "hooks": [{
            "type": "command",
            "command": f"{ahclaude_cmd} claude prompt"
        }]
    }]

    # 工具执行（紧接的模型请求）前重新激活 token，避免审批弹窗久未确认导致 key 失活
    settings["hooks"]["PreToolUse"] = [{
        "hooks": [{
            "type": "command",
            "command": f"{ahclaude_cmd} claude activate"
        }]
    }]

    settings["hooks"]["SessionStart"] = [{
        "matcher": "startup|resume",
        "hooks": [{
            "type": "command",
            "command": f"{ahclaude_cmd} claude start"
        }]
    }]

    save_settings(settings)


def configure_env(login_info: dict):
    settings = load_settings()

    if "env" not in settings:
        settings["env"] = {}

    env = {
        **AHCLAUDE_ENV_BASE,
        "ANTHROPIC_BASE_URL": get_claude_base_url(),
        "ANTHROPIC_AUTH_TOKEN": login_info["api_key"],
        "ANTHROPIC_MODEL": login_info["model"],
        "ANTHROPIC_DEFAULT_HAIKU_MODEL": login_info["model"],
        "ANTHROPIC_DEFAULT_SONNET_MODEL": login_info["model"],
        "ANTHROPIC_DEFAULT_OPUS_MODEL": login_info["model"],
    }

    for key, value in env.items():
        settings["env"][key] = value

    save_settings(settings)


def install():
    print("=" * 50)
    print("auto++ 安装向导")
    print("=" * 50)
    print()

    try:
        print("[步骤 1/5] 初始化目录...")
        create_directory()

        print()
        print("[步骤 2/5] 用户登录...")
        login_info = cmd_login.ensure_login()

        print()
        print("[步骤 3/5] 选择模型...")
        cmd_model.run_model_selector_interactive(login_info, product="claude")

        print()
        print("[步骤 4/5] 检查现有配置...")
        warn_overwrite()

        print()
        print("[步骤 5/5] 配置 Hooks 和环境变量...")
        configure_hooks()

        print()
        configure_env(login_info)

        print()
        print("=" * 50)
        log_success("安装完成!")
        print("=" * 50)
        print(f"  登录用户: {login_info['username']}")
        models = login_info.get("models", [])
        model_names = login_info.get("model_names", {})
        if models:
            current_model = login_info['model']
            print(f"  当前模型: {model_names.get(current_model, current_model)}")
        print()
        print("请重启 Claude Code 以加载配置")
        print("首次加载后如果 Hooks 页面提示 review / trust，请手动信任 auto++ 安装的 hooks。")

    except KeyboardInterrupt:
        log_warning("\n安装已取消")
        sys.exit(1)
    except Exception as e:
        log_error(f"安装失败: {e}")
        sys.exit(1)


if __name__ == "__main__":
    install()
